def main():
    source = json.loads(Path("source.json").read_text())
    assert len(source) == 24
    assert set(drafts) == {article["number"] for article in source}
    answer = []
    for article in source:
        item = {key: article[key] for key in ("code_id", "source_id", "source_sha256", "number")}
        item.update(drafts[article["number"]])
        item["status"] = "rewrite_draft"
        answer.append(item)
    Path("answer.json").write_text(json.dumps(answer, ensure_ascii=False, indent=2) + "\n")


if __name__ == "__main__":
    main()
